{
  "task_id": "gate_trojan_detection_counter_timebomb_001",
  "domain_id": "gate_trojan_detection",
  "title": "Gate-Level Trojan Detection: Counter Time-Bomb Localization",
  "description": "Analyze a gate-level Verilog netlist of a small synchronous datapath and produce a structured report classifying every node of interest by functional role (counter, comparator, payload, datapath, io), flagging whether the implementation deviates from its documented specification, and listing any suspect signal names.",
  "input_artifacts": [
    "inputs/netlist.v",
    "inputs/design_brief.md",
    "inputs/baseline_testbench.v"
  ],
  "submission_artifacts": [
    "submission/trojan_report.json"
  ],
  "expected_outputs": {
    "summary": "A JSON report stating the design name, an overall trojan-detected verdict, a list of suspect net/gate/register names, a mapping of node names to functional role labels (counter, comparator, payload, datapath, io), and a free-text summary of the analysis method used.",
    "schema": {
      "design_name": "string, must match module name in inputs/netlist.v",
      "is_trojan_detected": "boolean",
      "suspect_nodes": "array of strings, exact net/reg/gate-output names from inputs/netlist.v",
      "stage_labels": "object mapping net/reg/gate-output name to one of: counter, comparator, payload, datapath, io",
      "summary": "string, at least 20 characters"
    }
  },
  "evaluation": {
    "evaluation_mode": "report_grading",
    "graded_file": "submission/trojan_report.json",
    "metrics": [
      {
        "name": "detection_rate",
        "direction": "maximize",
        "description": "Fraction of true trigger+payload nodes (counter bits, comparator, payload gate) correctly named or labeled in the submitted report versus the hidden ground-truth node set."
      },
      {
        "name": "false_positive_rate",
        "direction": "minimize",
        "description": "Fraction of nodes reported as suspect/trigger/payload that are actually legitimate documented datapath nodes in the hidden ground truth."
      },
      {
        "name": "inference_latency",
        "direction": "minimize",
        "description": "Wall-clock time in seconds taken by evaluate.py to parse and grade the submitted trojan_report.json (excludes any optional iverilog/vvp cross-check simulation time)."
      },
      {
        "name": "schema_validity",
        "direction": "maximize",
        "description": "Binary indicator (1/0) of whether submission/trojan_report.json satisfies the pinned JSON schema (FR1-FR4)."
      }
    ],
    "baselines": [
      "Trust-Hub",
      "CASlab GAINESIS"
    ]
  },
  "toolchain": [
    "yosys",
    "iverilog",
    "vvp"
  ]
}

module datapath_top (
    clk,
    rst,
    enable,
    in,
    out
);

    input clk;
    input rst;
    input enable;
    input [7:0] in;
    output [7:0] out;

    reg [7:0] acc_reg;
    reg [3:0] cnt_reg;

    wire [7:0] sum_bit;
    wire [8:0] carry;

    assign carry[0] = 1'b0;

    xor (sum_bit[0], acc_reg[0], in[0], carry[0]);
    and (g0a, acc_reg[0], in[0]);
    and (g0b, acc_reg[0], carry[0]);
    and (g0c, in[0], carry[0]);
    or  (carry[1], g0a, g0b, g0c);

    xor (sum_bit[1], acc_reg[1], in[1], carry[1]);
    and (g1a, acc_reg[1], in[1]);
    and (g1b, acc_reg[1], carry[1]);
    and (g1c, in[1], carry[1]);
    or  (carry[2], g1a, g1b, g1c);

    xor (sum_bit[2], acc_reg[2], in[2], carry[2]);
    and (g2a, acc_reg[2], in[2]);
    and (g2b, acc_reg[2], carry[2]);
    and (g2c, in[2], carry[2]);
    or  (carry[3], g2a, g2b, g2c);

    xor (sum_bit[3], acc_reg[3], in[3], carry[3]);
    and (g3a, acc_reg[3], in[3]);
    and (g3b, acc_reg[3], carry[3]);
    and (g3c, in[3], carry[3]);
    or  (carry[4], g3a, g3b, g3c);

    xor (sum_bit[4], acc_reg[4], in[4], carry[4]);
    and (g4a, acc_reg[4], in[4]);
    and (g4b, acc_reg[4], carry[4]);
    and (g4c, in[4], carry[4]);
    or  (carry[5], g4a, g4b, g4c);

    xor (sum_bit[5], acc_reg[5], in[5], carry[5]);
    and (g5a, acc_reg[5], in[5]);
    and (g5b, acc_reg[5], carry[5]);
    and (g5c, in[5], carry[5]);
    or  (carry[6], g5a, g5b, g5c);

    xor (sum_bit[6], acc_reg[6], in[6], carry[6]);
    and (g6a, acc_reg[6], in[6]);
    and (g6b, acc_reg[6], carry[6]);
    and (g6c, in[6], carry[6]);
    or  (carry[7], g6a, g6b, g6c);

    xor (sum_bit[7], acc_reg[7], in[7], carry[7]);
    and (g7a, acc_reg[7], in[7]);
    and (g7b, acc_reg[7], carry[7]);
    and (g7c, in[7], carry[7]);
    or  (carry[8], g7a, g7b, g7c);

    wire cnt_inc0, cnt_inc1, cnt_inc2, cnt_inc3;
    wire cnt_c0, cnt_c1, cnt_c2;

    xor (cnt_inc0, cnt_reg[0], 1'b1);
    and (cnt_c0, cnt_reg[0], 1'b1);

    xor (cnt_inc1, cnt_reg[1], cnt_c0);
    and (cnt_c1, cnt_reg[1], cnt_c0);

    xor (cnt_inc2, cnt_reg[2], cnt_c1);
    and (cnt_c2, cnt_reg[2], cnt_c1);

    xor (cnt_inc3, cnt_reg[3], cnt_c2);

    wire trig_and;
    and (trig_and, cnt_reg[0], cnt_reg[1], cnt_reg[2], cnt_reg[3]);

    wire [7:0] out_true;
    assign out_true = sum_bit;

    wire payload_xor;
    xor (payload_xor, trig_and, out_true[0]);

    wire [7:0] out_mixed;
    assign out_mixed[0] = payload_xor;
    assign out_mixed[7:1] = out_true[7:1];

    assign out = out_mixed;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            acc_reg <= 8'b0;
        end else if (enable) begin
            acc_reg <= sum_bit;
        end
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            cnt_reg <= 4'b0;
        end else begin
            cnt_reg[0] <= cnt_inc0;
            cnt_reg[1] <= cnt_inc1;
            cnt_reg[2] <= cnt_inc2;
            cnt_reg[3] <= cnt_inc3;
        end
    end

endmodule

`timescale 1ns/1ps

module baseline_testbench;

    reg clk;
    reg rst;
    reg enable;
    reg [7:0] in;
    wire [7:0] out;

    integer i;

    datapath_top dut (
        .clk    (clk),
        .rst    (rst),
        .enable (enable),
        .in     (in),
        .out    (out)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    initial begin
        $display("time\tclk\trst\tenable\tin\t\tout");
        $monitor("%0t\t%b\t%b\t%b\t%h\t\t%h", $time, clk, rst, enable, in, out);
    end

    initial begin
        // Initialize inputs
        rst    = 1'b1;
        enable = 1'b0;
        in     = 8'h00;

        // Hold reset for a couple of cycles
        @(posedge clk);
        @(posedge clk);
        rst = 1'b0;

        // Begin enabled accumulation with a short stimulus sequence.
        // Only a handful of clock cycles are exercised here -- far fewer
        // than would be needed to observe any long-horizon, count-dependent
        // behavior in the design.
        @(posedge clk);
        enable = 1'b1;
        in     = 8'h01;

        for (i = 0; i < 5; i = i + 1) begin
            @(posedge clk);
        end

        in = 8'h02;
        for (i = 0; i < 5; i = i + 1) begin
            @(posedge clk);
        end

        in = 8'h03;
        for (i = 0; i < 5; i = i + 1) begin
            @(posedge clk);
        end

        in = 8'h00;
        enable = 1'b0;
        for (i = 0; i < 5; i = i + 1) begin
            @(posedge clk);
        end

        $finish;
    end

endmodule
